{
  "document_type": "lease",
  "lessor": "Shantou Yunjia Fashion Clothing Co., Ltd.",
  "lessee": "Shantou Big Tree Toys Co., Ltd",
  "premises_address": "South Part 1, Nanshe Area, Pengnan Industrial Park on North Yingbinbei Road in Waisha Town of Longhu District in Shantou City",
  "area": null,
  "start_date": "2011-01-01",
  "end_date": "2021-12-31",
  "rent": {
    "amount": 72000,
    "currency": "CNY",
    "period": "year"
  },
  "indexation": "none",
  "red_flags": [
    {
      "type": "sublease_permitted",
      "quote": "Party A shall have the rights to terminate the contract and take back the leased property if Party B has conducted one of the following activities: 1) Sublease, underlease, transfer, lend, pool, contribute to an equity interest, or exchange the space with others without Party A’s permission."
    },
    {
      "type": "tenant_break_option",
      "quote": "After expiration of this lease contract, if Party A decides to continue leasing out the property, Party B has the right of first refusal to lease the property."
    },
    {
      "type": "tenant_break_option",
      "quote": "When the contract expires and Party B fails to find another location to move to, Party B shall negotiate with Party A to extend the lease term."
    },
    {
      "type": "tenant_break_option",
      "quote": "After expiration of this contract, if Party B continues to use the property without the consent of Party A, besides regular rent Party B shall pay to Party A the penalty equivalent to 0.05% of the rent for each day after expiration date, and Party A keeps the right to terminate the lease contract."
    },
    {
      "type": "tenant_break_option",
      "quote": "If Party B wants to exchange the use of the property with a third party, Party B shall obtain the consent of Party A, and Party A shall support Party B’s reasonable requests."
    },
    {
      "type": "tenant_break_option",
      "quote": "If Party A lists the property for sale, Party A shall give notice to Party B three months in advance. Under the same condition, Party B has the first right of refusal to purchase the property."
    },
    {
      "type": "tenant_break_option",
      "quote": "If the contract is terminated due to the above reasons, the rent payable shall be calculated for the actual use days, and Party A shall refund for any overpayment and Party B shall make supplemental payment for any deficiency."
    }
  ]
}
